//    half the IQR either. Compute it independently to be sure.
val sorted = signal.sorted()
val medianAgain = (sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
val madByHand = signal.map { abs(it - medianAgain) }.sorted().let { (it[n / 2 - 1] + it[n / 2]) / 2.0 }
